"554 :   private boolean ensurePropertyDeclaredHelper(
555 :       Node getprop, ObjectType objectType) {
556 :     String propName = getprop.getLastChild().getString();
557 :     String qName = getprop.getQualifiedName();
558 :     if (qName != null) {
559 :       Var var = syntacticScope.getVar(qName);
560 :       if (var != null && !var.isTypeInferred()) {
561 :         // Handle normal declarations that could not be addressed earlier.
562 :         if (propName.equals("prototype") ||
563 :         // Handle prototype declarations that could not be addressed earlier.
564 :             (!objectType.hasOwnProperty(propName) &&
565 :              (!objectType.isInstanceType() ||
566 :                  (var.isExtern() && !objectType.isNativeObjectType())))) {
567 :           return objectType.defineDeclaredProperty(
568 :               propName, var.getType(), getprop);
569 :         }
570 :       }
571 :     }
572 :     return false;
573 :   }"

